a:1:{s:55:"../../../app/Http/Controllers/AdminCourseController.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:42:"App\Http\Controllers\AdminCourseController";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:941:"/**
 * The admin course catalog (US-705, §15.0–§17.0). Lists every course in
 * order_num order (the single ordering mechanism, preserved) and edits the
 * catalog fields plus status. Business logic stays in CourseService — this
 * controller only plugs the validated, whitelisted payload into it and renders
 * views. Course creation and deletion are out of scope for this story (§14.0
 * no-destructive-operation posture): only existing courses are editable.
 *
 * Course status changes are access gates (US-705, confirmed): locking or
 * drafting a course seals its missions and Boss Challenge, blocks all new
 * progress/XP/achievement accrual by URL, and never rewrites recorded
 * progress (CourseService writes only the course row). A refused update is
 * an InvalidArgumentException and is flashed back; the audit trail already
 * carries the failed row by the time it throws (same success/failed
 * discipline as US-704).
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:20:"App\Http\Controllers";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:7:{s:24:"admincourseupdaterequest";s:42:"App\Http\Requests\AdminCourseUpdateRequest";s:6:"course";s:17:"App\Models\Course";s:4:"user";s:15:"App\Models\User";s:13:"courseservice";s:26:"App\Services\CourseService";s:16:"redirectresponse";s:32:"Illuminate\Http\RedirectResponse";s:4:"view";s:20:"Illuminate\View\View";s:24:"invalidargumentexception";s:24:"InvalidArgumentException";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";s:31:"App\Http\Controllers\Controller";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:4:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";N;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:1:{i:0;O:53:"PHPStan\Dependency\ExportedNo