 * an unbounded computation (§44/§45).
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:17:"App\Http\Requests";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:5:{s:15:"timelineservice";s:28:"App\Services\TimelineService";s:6:"carbon";s:13:"Carbon\Carbon";s:11:"formrequest";s:38:"Illuminate\Foundation\Http\FormRequest";s:4:"rule";s:26:"Illuminate\Validation\Rule";s:9:"validator";s:31:"Illuminate\Validation\Validator";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";s:38:"Illuminate\Foundation\Http\FormRequest";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:4:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:9:"authorize";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:4:"bool";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:0:{}s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀attributes";a:0:{}}i:1;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:5