a:1:{s:48:"../../../app/Services/CourseAnalyticsService.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:35:"App\Services\CourseAnalyticsService";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:1077:"/**
 * Per-course aggregate analytics for the teacher area (US-607, §24.0-§26.0).
 *
 * Every metric is calculated from real records in SQL-level aggregation queries
 * (GROUP BY over the progress and assessment-attempt tables), never by
 * iterating the roster through the per-student services. The state vocabulary
 * still matches the student-facing services exactly: COMPLETED is
 * hasPassed() (a history 'passed' attempt), READY is isUnlocked() (all
 * missions done AND an active assessment, so a student who finished a course
 * whose challenge is not open stays in-progress), and engagement is any
 * Progress row on the course. CourseAnalyticsTest locks that equivalence by
 * comparing every fixture student's bucket against the per-student services.
 *
 * The bucket counts partition the student fleet per course, so NOT-STARTED is
 * the fleet minus the engaged, and the four counts always sum to the fleet
 * size. Courses render in order_num; locked/draft courses and courses with
 * zero missions are excluded (the same universe the student side renders).
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:12:"App\Services";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:6:{s:10:"assessment";s:21:"App\Models\Assessment";s:6:"course";s:17:"App\Models\Course";s:7:"mission";s:18:"App\Models\Mission";s:4:"user";s:15:"App\Models\User";s:10:"collection";s:29:"Illuminate\Support\Collection";s:2:"db";s:29:"Illuminate\Support\Facades\DB";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:2:{i:0;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:18:"DISTRIBUTION_BANDS";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:42:"['0-24', '25-49', '50-74', '75-99', '100']";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀public";b:1;s:67:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀private";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀final";b:0;s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:472:"/**
     * Completion-percentage band labels for the distribution (§53.0). A
     * histogram is the one chart that genuinely adds information over the four
     * bucket counts: bucket counts hide whether in-progress students cluster
     * at the start, spread across the course, or sit just short of the
     * challenge. The distribution is keyed by band order (0..4), not by these
     * labels, because PHP coerces the numeric "100" label to an integer key.
     */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:12:"App\Services";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:6:{s:10:"assessment";s:21:"App\Models\Assessment";s:6:"course";s:17:"App\Models\Course";s:7:"mission";s:18:"App\Models\Mission";s:4:"user";s:15:"App\Models\User";s:10:"collection";s:29:"Illuminate\Support\Collection";s:2:"db";s:29:"Illuminate\Support\Facades\DB";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}}i:1;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:8:"overview";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:347:"/**
