a:1:{s:40:"../../../app/Services/SectionService.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:27:"App\Services\SectionService";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:717:"/**
 * The only write path for course sections (US-706, §18.0). Sections are
 * the middle level of the Course → Section → Mission hierarchy: they group
 * missions inside a course and carry no status of their own — the access
 * gate for everything beneath them sits on course.status (US-705), never on
 * the section row.
 *
 * update() writes ONLY the section row (title / description / order_num);
 * it never selects, deletes, or rewrites the404_missions or the404_progress,
 * so the hierarchy and every student's per-mission progress stay intact.
 * Sections are listed per-course in order_num order — the same single
 * ordering key the learning path uses — and nothing here re-orders missions.
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:12:"App\Services";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:5:{s:6:"course";s:17:"App\Models\Course";s:7:"section";s:18:"App\Models\Section";s:4:"user";s:15:"App\Models\User";s:10:"collection";s:29:"Illuminate\Support\Collection";s:24:"invalidargumentexception";s:24:"InvalidArgumentException";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:3:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";N;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:1:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:5:"audit";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:30:"App\Servi