a:1:{s:40:"../../../app/Services/StudentService.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:27:"App\Services\StudentService";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:964:"/**
 * Builds the teacher-facing student overview (US-602): a paginated list of every
 * student with their current course, mission progress, assessment status,
 * competency summary, and last activity.
 *
 * Everything is composed from the existing Phase 5 services — CourseProgressService,
 * AssessmentService, CompetencyService, DashboardService, TimelineService — and never
 * re-derives their formulas for a teacher-specific view. Search and filters are applied
 * server-side; the page takes no student identifier, so a client cannot pivot
 * the list onto a specific user.
 *
 * Rows are computed for every matching student, then filtered and paginated in
 * memory. That ordering is correct-by-construction for the current-course
 * filters (derived from progress/assessment history, not stored columns). It is
 * fine at the fleet's current scale; DB-level pagination of these computed
 * filters is a known optimisation only if the roster grows.
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:12:"App\Services";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:5:{s:6:"course";s:17:"App\Models\Course";s:4:"user";s:15:"App\Models\User";s:20:"lengthawarepaginator";s:42:"Illuminate\Pagination\LengthAwarePaginator";s:9:"paginator";s:31:"Illuminate\Pagination\Paginator";s:10:"collection";s:29:"Illuminate\Support\Collection";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:5:{i:0;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:8:"PER_PAGE";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:2:"10";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀public";b:1;s:67:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀private";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀final";b:0;s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀phpDoc";N;}i:1;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\Exporte