     * Beat types the teacher feed's event-type filter accepts, in the same
     * vocabulary the timeline itself produces.
     */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:12:"App\Services";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:11:{s:8:"activity";s:19:"App\Models\Activity";s:17:"assessmentattempt";s:28:"App\Models\AssessmentAttempt";s:8:"progress";s:19:"App\Models\Progress";s:7:"section";s:18:"App\Models\Section";s:4:"user";s:15:"App\Models\User";s:13:"xptransaction";s:24:"App\Models\XpTransaction";s:6:"carbon";s:13:"Carbon\Carbon";s:7:"builder";s:36:"Illuminate\Database\Eloquent\Builder";s:20:"lengthawarepaginator";s:42:"Illuminate\Pagination\LengthAwarePaginator";s:9:"paginator";s:31:"Illuminate\Pagination\Paginator";s:10:"collection";s:29:"Illuminate\Support\Collection";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}}i:2;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:19:"DEFAULT_WINDOW_DAYS";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:2:"14";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀public";b:1;s:67:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀private";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀final";b:0;s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:203:"/**
     * The default date-window span for the teacher feed, ending today when no
