a:1:{s:37:"../../../app/Services/UserService.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:24:"App\Services\UserService";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:1109:"/**
 * Admin user management (US-703, §9.0–§12.0): a server-side searched, filtered,
 * and paginated directory of every account, plus whitelisted create/update
 * paths. The controller and requests never hand raw client input to the model:
 * the server decides which fields are writable, validates them all, and the
 * password is always a fresh hash of the plaintext the client submits.
 *
 * - search and role filter run in SQL (no full-table-to-JS, §9.0);
 * - "last activity" reuses TimelineService::events — one beat vocabulary, no
 *   new activity mechanism (§9.0);
 * - create keeps status on its 'active' column default and allows only
 *   CREATABLE_ROLES; update additionally carries optional role/status changes
 *   that are validated (US-704) and guarded against self-demotion /
 *   self-deactivation / dropping the active-admin fleet below two (§13).
 *
 * Username search uses `%term%` LIKE, same shape as StudentService. Rows are
 * computed for every matching user then paginated in memory; acceptable at
 * fleet scale and deliberately consistent with the roster's approach.
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:12:"App\Services";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:8:{s:23:"userprotectionexception";s:38:"App\Exceptions\UserProtectionException";s:4:"user";s:15:"App\Models\User";s:6:"carbon";s:13:"Carbon\Carbon";s:20:"lengthawarepaginator";s:42:"Illuminate\Pagination\LengthAwarePaginator";s:9:"paginator";s:31:"Illuminate\Pagination\Paginator";s:10:"collection";s:29:"Illuminate\Support\Collection";s:4:"hash";s:31:"Illuminate\Support\Facades\Hash";s:24:"invalidargumentexception";s:24:"InvalidArgumentException";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:8:{i:0;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:8:"PER_PAGE";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:2:"10";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀public";b:1;s:67:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀private";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀final";b:0;s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀phpDoc";N;}i:1;O:58